function tokenizeMath(expression){
  const source=String(expression).trim();if(source.length>160||!/^[\d\sA-Za-z_.+\-*/%()]+$/.test(source))throw new Error("Unsupported expression");const tokens=source.match(/\d+(?:\.\d+)?|[A-Za-z_]\w*|[()+\-*/%]/g)||[];if(tokens.join("").length!==source.replace(/\s/g,"").length)throw new Error("Invalid expression");return tokens;
}
function safeArithmetic(expression,variables={}){
  const tokens=tokenizeMath(expression),output=[],ops=[],precedence={"+":1,"-":1,"*":2,"/":2,"%":2};let previous="(";
  tokens.forEach(token=>{if(/^\d/.test(token))output.push(Number(token));else if(/^[A-Za-z_]/.test(token)){if(!Object.prototype.hasOwnProperty.call(variables,token))throw new Error("Unknown value: "+token);const n=Number(variables[token]);if(!Number.isFinite(n))throw new Error(token+" is not numeric");output.push(n)}else if(token==="("){ops.push(token)}else if(token===")"){while(ops.length&&ops.at(-1)!=="(")output.push(ops.pop());if(ops.pop()!=="(")throw new Error("Mismatched parentheses")}else{if(token==="-"&&(previous==="("||precedence[previous]))output.push(0);while(ops.length&&precedence[ops.at(-1)]>=precedence[token])output.push(ops.pop());ops.push(token)}previous=token});while(ops.length){const op=ops.pop();if(op==="(")throw new Error("Mismatched parentheses");output.push(op)}
  const stack=[];output.forEach(token=>{if(typeof token==="number")stack.push(token);else{const b=stack.pop(),a=stack.pop();if(a===undefined||b===undefined)throw new Error("Invalid expression");if((token==="/"||token==="%")&&b===0)throw new Error("Division by zero");stack.push(token==="+"?a+b:token==="-"?a-b:token==="*"?a*b:token==="/"?a/b:a%b)}});if(stack.length!==1||!Number.isFinite(stack[0]))throw new Error("Invalid result");return Math.round(stack[0]*1e10)/1e10;
}
function evaluateValue(source,env={}){
  let value=String(source).trim();if((value.startsWith('"')&&value.endsWith('"'))||(value.startsWith("'")&&value.endsWith("'")))return value.slice(1,-1).replace(/\\n/g,"\n");if(/^f["']/.test(value)){const body=value.slice(2,-1);return body.replace(/\{([A-Za-z_]\w*)\}/g,(_,name)=>cleanText(env[name]??"",200))}if(Object.prototype.hasOwnProperty.call(env,value))return env[value];try{return safeArithmetic(value,env)}catch{return cleanText(value,300)}
}
function runSafeCode(code,language="Python"){
  const source=String(code).slice(0,12000),env={},out=[];const lines=source.split(/\r?\n/).slice(0,300);
  for(const raw of lines){const line=raw.trim();if(!line||line.startsWith("#")||line.startsWith("//")||line.startsWith("import ")||line.startsWith("from ")||/[{}:]$/.test(line))continue;let match;
    if((match=line.match(/^(?:let|const|var|int|double|String|auto)?\s*([A-Za-z_]\w*)\s*=\s*(.+?);?$/))&&!/^(if|for|while)\b/.test(line)){const rhs=match[2].replace(/;$/,"");env[match[1]]=evaluateValue(rhs,env);continue}
    const patterns=[/^print\((.*)\)\s*;?$/,/^console\.log\((.*)\)\s*;?$/,/^System\.out\.println\((.*)\)\s*;?$/,/^std::cout\s*<<\s*(.*?)\s*(?:<<\s*std::endl)?\s*;?$/,/^cout\s*<<\s*(.*?)\s*(?:<<\s*endl)?\s*;?$/];for(const pattern of patterns){match=line.match(pattern);if(match){const parts=match[1].split(/\s*,\s*|\s*<<\s*/).filter(Boolean);out.push(parts.map(part=>evaluateValue(part,env)).join(" "));break}}
  }return out.length?out.join("\n"):`${language} source parsed safely. No printable output.`;
}
