function initIDE(win){
  const editor=$("[data-ide-editor]",win),output=$("[data-ide-output]",win),tab=$("[data-ide-tab]",win),language=$("[data-ide-language]",win);let current="main.py";
  const updateLines=()=>{$("[data-line-numbers]",win).textContent=Array.from({length:Math.max(1,editor.value.split(/\r?\n/).length)},(_,i)=>i+1).join("\n")};editor.addEventListener("input",()=>{IDE_FILES[current]=editor.value;updateLines()});$$('[data-ide-file]',win).forEach(button=>button.addEventListener("click",()=>{IDE_FILES[current]=editor.value;current=button.dataset.ideFile;editor.value=IDE_FILES[current];tab.textContent=current;$$('[data-ide-file]',win).forEach(item=>item.classList.toggle("active",item===button));language.value=current.endsWith(".yml")?"Python":current.endsWith(".py")?"Python":language.value;updateLines()}));
  $("[data-ide-run]",win).addEventListener("click",()=>{if(current.endsWith(".yml")){output.textContent="GUI YAML validated. Open GUI Designer to render it.";return}try{output.textContent=runSafeCode(editor.value,language.value)+"\n\nProcess finished with exit code 0"}catch(error){output.textContent="Error: "+cleanText(error.message,200)}});$("[data-ide-clear]",win).addEventListener("click",()=>output.textContent="");updateLines();
}

const COMPONENT_DEFAULTS={label:{text:"Label",w:130},input:{text:"Input",w:170},button:{text:"Calculate",w:120},output:{text:"Result",w:170}};
function newDesignerProject(){return{name:"Untitled",components:[],connections:[],selected:null,format:"yaml",connectMode:false,connectStart:null}}
function normalizeComponent(raw,index){const type=["label","input","button","output"].includes(raw.type)?raw.type:"label",base=COMPONENT_DEFAULTS[type];return{id:slug(raw.id||type+(index+1)).replace(/-/g,"_").slice(0,24),type,text:cleanText(raw.text||base.text,80),x:clamp(Number(raw.x)||40,0,680),y:clamp(Number(raw.y)||40,0,400),w:clamp(Number(raw.w)||base.w,60,500),operation:["none","add","subtract","multiply","divide","formula","join","upper","lower","clear"].includes(raw.operation)?raw.operation:"none",formula:cleanText(raw.formula||"",120)}}
function validateProject(raw){const source=raw&&typeof raw==="object"?raw:{};const components=Array.isArray(source.components)?source.components.slice(0,50).map(normalizeComponent):[],ids=new Set(),unique=[];components.forEach((item,index)=>{let id=item.id||"component"+(index+1);while(ids.has(id))id=id+"_"+(index+1);item.id=id;ids.add(id);unique.push(item)});const connections=Array.isArray(source.connections)?source.connections.slice(0,100).map(c=>({from:cleanText(c.from,24),to:cleanText(c.to,24)})).filter(c=>ids.has(c.from)&&ids.has(c.to)&&c.from!==c.to):[];return{name:cleanText(source.name||"Untitled",48),components:unique,connections,selected:null,format:"yaml",connectMode:false,connectStart:null}}
function yamlQuote(value){return JSON.stringify(cleanText(value,160))}
function projectToYAML(project){const lines=[`app: ${yamlQuote(project.name)}`,"components:"];project.components.forEach(c=>{lines.push(`  - id: ${c.id}`,`    type: ${c.type}`,`    text: ${yamlQuote(c.text)}`,`    x: ${Math.round(c.x)}`,`    y: ${Math.round(c.y)}`,`    width: ${Math.round(c.w)}`);if(c.type==="button"){lines.push(`    operation: ${c.operation}`);if(c.formula)lines.push(`    formula: ${yamlQuote(c.formula)}`)}});lines.push("connections:");project.connections.forEach(c=>lines.push(`  - from: ${c.from}`,`    to: ${c.to}`));return lines.join("\n")}
function projectToPythonUI(project){const lines=["from portfolio_os import App",`ui = App(${JSON.stringify(project.name)}, width=760, height=450)`,""];project.components.forEach(c=>{const method=c.type;lines.push(`ui.${method}(${JSON.stringify(c.id)}, text=${JSON.stringify(c.text)}, x=${Math.round(c.x)}, y=${Math.round(c.y)}, width=${Math.round(c.w)}${c.type==="button"?`, operation=${JSON.stringify(c.operation)}, formula=${JSON.stringify(c.formula)}`:""})`)});lines.push("");project.connections.forEach(c=>lines.push(`ui.connect(${JSON.stringify(c.from)}, ${JSON.stringify(c.to)})`));lines.push("ui.run()");return lines.join("\n")}
function actionMap(project,button){const incoming=project.connections.filter(c=>c.to===button.id).map(c=>c.from),outgoing=project.connections.filter(c=>c.from===button.id).map(c=>c.to);return{incoming,outgoing}}
function pythonExpression(button,inputs,widgetSuffix=".get()"){
  const refs=inputs.length?inputs:["input1"];const vals=refs.map(id=>`${id}${widgetSuffix}`);if(button.operation==="join")return vals.join(' + " " + ');if(button.operation==="upper")return `${vals[0]}.upper()`;if(button.operation==="lower")return `${vals[0]}.lower()`;if(button.operation==="formula"&&button.formula){let formula=button.formula;refs.forEach((id,i)=>{formula=formula.replace(new RegExp(`\\b${id}\\b|\\binput${i+1}\\b`,"g"),`float(${id}${widgetSuffix})`)});return formula}const op={add:" + ",subtract:" - ",multiply:" * ",divide:" / "}[button.operation]||" + ";return vals.map(v=>`float(${v})`).join(op)}
function projectToTkinter(project){const lines=["import tkinter as tk","from tkinter import ttk","","root = tk.Tk()",`root.title(${JSON.stringify(project.name)})`,`root.geometry("760x450")`,""];project.components.forEach(c=>{if(c.type==="input")lines.push(`${c.id} = ttk.Entry(root)`,`${c.id}.place(x=${Math.round(c.x)}, y=${Math.round(c.y)}, width=${Math.round(c.w)})`);else if(c.type==="output")lines.push(`${c.id}_var = tk.StringVar(value=${JSON.stringify(c.text)})`,`${c.id} = ttk.Label(root, textvariable=${c.id}_var)`,`${c.id}.place(x=${Math.round(c.x)}, y=${Math.round(c.y)}, width=${Math.round(c.w)})`);else if(c.type==="label")lines.push(`${c.id} = ttk.Label(root, text=${JSON.stringify(c.text)})`,`${c.id}.place(x=${Math.round(c.x)}, y=${Math.round(c.y)}, width=${Math.round(c.w)})`)});project.components.filter(c=>c.type==="button").forEach(button=>{const map=actionMap(project,button),target=map.outgoing[0]||project.components.find(c=>c.type==="output")?.id||"result";lines.push("",`def on_${button.id}():`);if(button.operation==="clear"){map.incoming.forEach(id=>lines.push(`    ${id}.delete(0, tk.END)`));lines.push(`    ${target}_var.set("")`)}else lines.push("    try:",`        value = ${pythonExpression(button,map.incoming)}`,`        ${target}_var.set(str(value))`,`    except (ValueError, ZeroDivisionError) as error:`,`        ${target}_var.set(f"Error: {error}")`);lines.push(`${button.id} = ttk.Button(root, text=${JSON.stringify(button.text)}, command=on_${button.id})`,`${button.id}.place(x=${Math.round(button.x)}, y=${Math.round(button.y)}, width=${Math.round(button.w)})`)});lines.push("","root.mainloop()");return lines.join("\n")}
function projectToPyQt(project){const lines=["import sys","from PyQt6.QtWidgets import QApplication, QWidget, QLabel, QLineEdit, QPushButton","","app = QApplication(sys.argv)","window = QWidget()",`window.setWindowTitle(${JSON.stringify(project.name)})`,`window.setGeometry(100, 100, 760, 450)`,""];project.components.forEach(c=>{const klass={label:"QLabel",input:"QLineEdit",button:"QPushButton",output:"QLabel"}[c.type];lines.push(`${c.id} = ${klass}(${JSON.stringify(c.text)}, window)`,`${c.id}.setGeometry(${Math.round(c.x)}, ${Math.round(c.y)}, ${Math.round(c.w)}, 34)`)});project.components.filter(c=>c.type==="button").forEach(button=>{const map=actionMap(project,button),target=map.outgoing[0]||"result";lines.push("",`def on_${button.id}():`,`    try:`,`        value = ${pythonExpression(button,map.incoming,".text()")}`,`        ${target}.setText(str(value))`,`    except (ValueError, ZeroDivisionError) as error:`,`        ${target}.setText(f"Error: {error}")`,`${button.id}.clicked.connect(on_${button.id})`)});lines.push("","window.show()","sys.exit(app.exec())");return lines.join("\n")}
function projectToKivy(project){const kv=["from kivy.app import App","from kivy.uix.floatlayout import FloatLayout","from kivy.uix.label import Label","from kivy.uix.textinput import TextInput","from kivy.uix.button import Button","","class GeneratedApp(App):","    def build(self):","        root = FloatLayout()"];project.components.forEach(c=>{const klass={label:"Label",input:"TextInput",button:"Button",output:"Label"}[c.type];kv.push(`        self.${c.id} = ${klass}(text=${JSON.stringify(c.text)}, size_hint=(None, None), size=(${Math.round(c.w)}, 40), pos=(${Math.round(c.x)}, ${Math.round(410-c.y)}))`,`        root.add_widget(self.${c.id})`)});project.components.filter(c=>c.type==="button").forEach(button=>kv.push(`        self.${button.id}.bind(on_press=self.on_${button.id})`));kv.push("        return root");project.components.filter(c=>c.type==="button").forEach(button=>{const map=actionMap(project,button),target=map.outgoing[0]||"result";kv.push("",`    def on_${button.id}(self, _button):`,`        try:`,`            value = ${pythonExpression(button,map.incoming.map(id=>"self."+id),".text")}`,`            self.${target}.text = str(value)`,`        except (ValueError, ZeroDivisionError) as error:`,`            self.${target}.text = f"Error: {error}"`)});kv.push("","GeneratedApp().run()");return kv.join("\n")}
function javaExpression(button,inputs){const vals=(inputs.length?inputs:["input1"]).map(id=>`${id}.getText()`);if(button.operation==="join")return `String.join(" ", ${vals.join(", ")})`;if(button.operation==="upper")return `${vals[0]}.toUpperCase()`;if(button.operation==="lower")return `${vals[0]}.toLowerCase()`;const op={add:" + ",subtract:" - ",multiply:" * ",divide:" / "}[button.operation]||" + ";return vals.map(v=>`Double.parseDouble(${v})`).join(op)}
function projectToSwing(project){const lines=["import javax.swing.*;","","public class GeneratedApp {","  public static void main(String[] args) {","    SwingUtilities.invokeLater(() -> {","      JFrame frame = new JFrame("+JSON.stringify(project.name)+");","      frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);","      frame.setSize(760, 450);","      frame.setLayout(null);"];project.components.forEach(c=>{const klass={label:"JLabel",input:"JTextField",button:"JButton",output:"JLabel"}[c.type];lines.push(`      ${klass} ${c.id} = new ${klass}(${JSON.stringify(c.text)});`,`      ${c.id}.setBounds(${Math.round(c.x)}, ${Math.round(c.y)}, ${Math.round(c.w)}, 34);`,`      frame.add(${c.id});`)});project.components.filter(c=>c.type==="button").forEach(button=>{const map=actionMap(project,button),target=map.outgoing[0]||"result";lines.push(`      ${button.id}.addActionListener(event -> {`,`        try {`,`          Object value = ${javaExpression(button,map.incoming)};`,`          ${target}.setText(String.valueOf(value));`,`        } catch (RuntimeException error) { ${target}.setText("Error: " + error.getMessage()); }`,`      });`)});lines.push("      frame.setVisible(true);","    });","  }","}");return lines.join("\n")}
function projectToWin32(project){const lines=["#include <windows.h>","#include <string>","","LRESULT CALLBACK WindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {","  static HWND controls[128];","  switch (msg) {","    case WM_CREATE:"];project.components.forEach((c,index)=>{const klass=c.type==="button"?"BUTTON":c.type==="input"?"EDIT":"STATIC",style=c.type==="input"?"WS_CHILD | WS_VISIBLE | WS_BORDER | ES_AUTOHSCROLL":"WS_CHILD | WS_VISIBLE";lines.push(`      controls[${index}] = CreateWindowA("${klass}", ${JSON.stringify(c.text)}, ${style}, ${Math.round(c.x)}, ${Math.round(c.y)}, ${Math.round(c.w)}, 34, hwnd, (HMENU)${1000+index}, nullptr, nullptr);`)});lines.push("      return 0;","    case WM_COMMAND:");project.components.filter(c=>c.type==="button").forEach(button=>{const index=project.components.indexOf(button);lines.push(`      if (LOWORD(wParam) == ${1000+index}) {`,`        // Native handler for ${button.operation}; read connected EDIT controls, calculate, then SetWindowText.`,`        MessageBeep(MB_OK);`,`      }`)});lines.push("      return 0;","    case WM_DESTROY: PostQuitMessage(0); return 0;","  }","  return DefWindowProc(hwnd, msg, wParam, lParam);","}","","int WINAPI WinMain(HINSTANCE instance, HINSTANCE, LPSTR, int show) {","  WNDCLASSA wc{}; wc.lpfnWndProc = WindowProc; wc.hInstance = instance; wc.lpszClassName = \"PortfolioGeneratedApp\"; RegisterClassA(&wc);",`  HWND hwnd = CreateWindowExA(0, wc.lpszClassName, ${JSON.stringify(project.name)}, WS_OVERLAPPEDWINDOW, CW_USEDEFAULT, CW_USEDEFAULT, 760, 450, nullptr, nullptr, instance, nullptr);`,"  ShowWindow(hwnd, show); MSG msg{}; while (GetMessage(&msg, nullptr, 0, 0)) { TranslateMessage(&msg); DispatchMessage(&msg); } return 0;","}");return lines.join("\n")}
function generateProjectCode(project,format){return({yaml:projectToYAML,python:projectToPythonUI,tkinter:projectToTkinter,pyqt:projectToPyQt,kivy:projectToKivy,swing:projectToSwing,win32:projectToWin32}[format]||projectToYAML)(project)}
function parseScalar(value){const raw=value.trim();if(/^".*"$/.test(raw)){try{return JSON.parse(raw)}catch{return raw.slice(1,-1)}}return raw}
function parseProjectYAML(source){const project={name:"Imported App",components:[],connections:[]};let section="",current=null;for(const raw of String(source).split(/\r?\n/).slice(0,1000)){const line=raw.trim();if(!line||line.startsWith("#"))continue;if(line.startsWith("app:")){project.name=parseScalar(line.slice(4));continue}if(line==="components:"){section="components";continue}if(line==="connections:"){section="connections";current=null;continue}if(section==="components"&&line.startsWith("- id:")){current={id:parseScalar(line.slice(5))};project.components.push(current);continue}if(section==="components"&&current&&line.includes(":")){const at=line.indexOf(":"),key=line.slice(0,at).trim(),value=parseScalar(line.slice(at+1));current[key==="width"?"w":key]=["x","y","width","w"].includes(key)?Number(value):value;continue}if(section==="connections"&&line.startsWith("- from:")){current={from:parseScalar(line.slice(7)),to:""};project.connections.push(current);continue}if(section==="connections"&&current&&line.startsWith("to:")){current.to=parseScalar(line.slice(3));continue}const arrow=line.match(/^-\s*([A-Za-z_]\w*)\s*->\s*([A-Za-z_]\w*)/);if(section==="connections"&&arrow)project.connections.push({from:arrow[1],to:arrow[2]})}return validateProject(project)}
function parseProjectPython(source){const project={name:"Python UI",components:[],connections:[]};const app=String(source).match(/App\((['"])(.*?)\1/);if(app)project.name=app[2];for(const line of String(source).split(/\r?\n/).slice(0,1000)){let match=line.match(/ui\.(label|input|button|output)\((['"])([A-Za-z_]\w*)\2,(.*)\)/);if(match){const args=match[4],get=(name,fallback="")=>{const value=args.match(new RegExp(`${name}=["']([^"']*)["']`));return value?value[1]:fallback},num=(name,fallback)=>Number(args.match(new RegExp(`${name}=(\\d+)`))?.[1]||fallback);project.components.push({type:match[1],id:match[3],text:get("text",COMPONENT_DEFAULTS[match[1]].text),x:num("x",40),y:num("y",40),w:num("width",COMPONENT_DEFAULTS[match[1]].w),operation:get("operation","none"),formula:get("formula","")});continue}match=line.match(/ui\.connect\((['"])([A-Za-z_]\w*)\1,\s*(['"])([A-Za-z_]\w*)\3\)/);if(match)project.connections.push({from:match[2],to:match[4]})}return validateProject(project)}

function initDesigner(win){
  const stage=$("[data-designer-stage]",win),wires=$("[data-designer-wires]",win),inspector=$("[data-inspector-form]",win),empty=$("[data-inspector-empty]",win),code=$("[data-designer-code]",win),connections=$("[data-connection-list]",win),connectButton=$("[data-connect-mode]",win);let project=validateProject(storage.get("portfolio-os:designer:"+slug(settings.profile),newDesignerProject()));
  const selected=()=>project.components.find(c=>c.id===project.selected);
  const save=()=>storage.set("portfolio-os:designer:"+slug(settings.profile),{name:project.name,components:project.components,connections:project.connections});
  const updateCode=()=>{code.value=generateProjectCode(project,project.format)};
  const renderWires=()=>{wires.replaceChildren();project.connections.forEach(connection=>{const a=project.components.find(c=>c.id===connection.from),b=project.components.find(c=>c.id===connection.to);if(!a||!b)return;const x1=a.x+a.w,y1=a.y+17,x2=b.x,y2=b.y+17,path=document.createElementNS("http://www.w3.org/2000/svg","path");path.setAttribute("d",`M ${x1} ${y1} C ${x1+50} ${y1}, ${x2-50} ${y2}, ${x2} ${y2}`);wires.append(path)})};
  const renderConnections=()=>{connections.replaceChildren();if(!project.connections.length){connections.append(make("small",null,"No connections yet."));return}project.connections.forEach((connection,index)=>{const button=make("button",null,`${connection.from} → ${connection.to}  ×`);button.type="button";button.addEventListener("click",()=>{project.connections.splice(index,1);render();save()});connections.append(button)})};
  const fillInspector=()=>{const item=selected();empty.hidden=Boolean(item);inspector.hidden=!item;if(!item)return;["id","text","x","y","w","operation","formula"].forEach(name=>{const field=inspector.elements[name];if(field)field.value=item[name]??""})};
  const chooseConnection=id=>{if(!project.connectStart){project.connectStart=id;render();toast("Connection started","Choose the destination component.");return}if(project.connectStart!==id&&!project.connections.some(c=>c.from===project.connectStart&&c.to===id))project.connections.push({from:project.connectStart,to:id});project.connectStart=null;render();save()};
  const wireElement=(node,item)=>{node.addEventListener("pointerdown",event=>{event.preventDefault();event.stopPropagation();if(project.connectMode){chooseConnection(item.id);return}project.selected=item.id;fillInspector();$$('.designer-element',stage).forEach(el=>el.classList.toggle("selected",el.dataset.id===item.id));const rect=stage.getBoundingClientRect(),startX=event.clientX,startY=event.clientY,startLeft=item.x,startTop=item.y;node.setPointerCapture(event.pointerId);const move=e=>{item.x=clamp(Math.round(startLeft+e.clientX-startX),0,stage.clientWidth-item.w);item.y=clamp(Math.round(startTop+e.clientY-startY),0,stage.clientHeight-34);node.style.left=item.x+"px";node.style.top=item.y+"px";renderWires();fillInspector()};const up=()=>{node.removeEventListener("pointermove",move);node.removeEventListener("pointerup",up);updateCode();save()};node.addEventListener("pointermove",move);node.addEventListener("pointerup",up)});node.addEventListener("keydown",event=>{if(event.key==="Delete"){project.components=project.components.filter(c=>c.id!==item.id);project.connections=project.connections.filter(c=>c.from!==item.id&&c.to!==item.id);project.selected=null;render();save()}})};
  const render=()=>{stage.querySelectorAll(".designer-element").forEach(node=>node.remove());project.components.forEach(item=>{const node=make("button","designer-element",item.type==="input"?item.text+"…":item.text);node.type="button";node.dataset.id=item.id;node.dataset.type=item.type;node.style.left=item.x+"px";node.style.top=item.y+"px";node.style.width=item.w+"px";node.title=item.id;node.classList.toggle("selected",project.selected===item.id);node.classList.toggle("connecting",project.connectStart===item.id);wireElement(node,item);stage.append(node)});$(".stage-empty",stage).classList.toggle("hidden",project.components.length>0);connectButton.classList.toggle("active",project.connectMode);renderWires();renderConnections();fillInspector();updateCode()};
  const add=type=>{const count=project.components.filter(c=>c.type===type).length+1,item=normalizeComponent({type,id:type+count,text:COMPONENT_DEFAULTS[type].text,x:45+(count-1)*25,y:45+(project.components.length%6)*52},project.components.length);project.components.push(item);project.selected=item.id;render();save()};
  $$('[data-component]',win).forEach(button=>{button.addEventListener("click",()=>add(button.dataset.component));button.addEventListener("dragstart",event=>event.dataTransfer.setData("text/plain",button.dataset.component))});stage.addEventListener("dragover",event=>event.preventDefault());stage.addEventListener("drop",event=>{event.preventDefault();const type=event.dataTransfer.getData("text/plain");if(!COMPONENT_DEFAULTS[type])return;add(type);const item=selected(),rect=stage.getBoundingClientRect();item.x=clamp(Math.round(event.clientX-rect.left),0,stage.clientWidth-item.w);item.y=clamp(Math.round(event.clientY-rect.top),0,stage.clientHeight-34);render();save()});stage.addEventListener("pointerdown",event=>{if(event.target===stage||event.target.classList.contains("stage-grid")){project.selected=null;fillInspector();$$('.designer-element',stage).forEach(el=>el.classList.remove("selected"))}});
  inspector.addEventListener("input",event=>{const item=selected();if(!item)return;const field=event.target.name;if(!field)return;if(["x","y","w"].includes(field))item[field]=Number(event.target.value)||0;else if(field==="id"){const old=item.id,next=slug(event.target.value).replace(/-/g,"_").slice(0,24)||old;if(!project.components.some(c=>c!==item&&c.id===next)){item.id=next;project.selected=next;project.connections.forEach(c=>{if(c.from===old)c.from=next;if(c.to===old)c.to=next})}}else item[field]=cleanText(event.target.value,field==="formula"?120:80);render();save()});
  $("[data-designer-delete]",win).addEventListener("click",()=>{const item=selected();if(!item)return;project.components=project.components.filter(c=>c!==item);project.connections=project.connections.filter(c=>c.from!==item.id&&c.to!==item.id);project.selected=null;render();save()});connectButton.addEventListener("click",()=>{project.connectMode=!project.connectMode;project.connectStart=null;render()});
  $("[data-designer-new]",win).addEventListener("click",()=>{project=newDesignerProject();render();save()});$("[data-designer-demo]",win).addEventListener("click",()=>{project=validateProject({name:"Connected Calculator",components:[{id:"input1",type:"input",text:"First number",x:65,y:80,w:180},{id:"input2",type:"input",text:"Second number",x:65,y:140,w:180},{id:"calculate",type:"button",text:"Add values",x:310,y:108,w:135,operation:"add"},{id:"result",type:"output",text:"Result",x:510,y:108,w:180}],connections:[{from:"input1",to:"calculate"},{from:"input2",to:"calculate"},{from:"calculate",to:"result"}]});render();save()});
  $$('[data-format]',win).forEach(button=>button.addEventListener("click",()=>{project.format=button.dataset.format;$$('[data-format]',win).forEach(item=>item.classList.toggle("active",item===button));updateCode()}));$("[data-code-apply]",win).addEventListener("click",()=>{try{if(project.format==="yaml")project=parseProjectYAML(code.value);else if(project.format==="python")project=parseProjectPython(code.value);else throw new Error("Apply code supports YAML and Python UI formats.");render();save();toast("Code applied","The canvas and connections were regenerated.")}catch(error){toast("Could not apply code",error.message)}});$("[data-code-download]",win).addEventListener("click",()=>downloadText(project.name+({yaml:".yml",python:".py",tkinter:"-tkinter.py",pyqt:"-pyqt.py",kivy:"-kivy.py",swing:".java",win32:".cpp"}[project.format]||".txt"),code.value));
  $("[data-designer-run]",win).addEventListener("click",()=>openCustomAppWindow({...project,name:project.name+" Preview"},"custom-preview-"+Date.now()));$("[data-designer-package]",win).addEventListener("click",()=>{try{const pkg={format:"portfolio-os-app/v1",name:project.name,icon:"◆",components:project.components,connections:project.connections,createdAt:new Date().toISOString()};installPackage(pkg);downloadText(slug(project.name)+".posapp",JSON.stringify(pkg,null,2),"application/json");toast("App packaged","Installed locally and downloaded as .posapp")}catch(error){toast("Package not created",cleanText(error.message,160))}});render();
}
function executeCustomAction(packageData,buttonId,root){const button=packageData.components.find(c=>c.id===buttonId),incoming=packageData.connections.filter(c=>c.to===buttonId).map(c=>c.from),outgoing=packageData.connections.filter(c=>c.from===buttonId).map(c=>c.to),values={},ordered=[];incoming.forEach((id,index)=>{const field=$(`[data-custom-id="${cssEscape(id)}"]`,root),value=field?.value??field?.textContent??"";values[id]=value;values["input"+(index+1)]=value;ordered.push(value)});let result="";try{switch(button.operation){case"add":result=ordered.reduce((a,b)=>a+Number(b),0);break;case"subtract":result=ordered.slice(1).reduce((a,b)=>a-Number(b),Number(ordered[0]||0));break;case"multiply":result=ordered.reduce((a,b)=>a*Number(b),1);break;case"divide":result=ordered.slice(1).reduce((a,b)=>{if(Number(b)===0)throw new Error("Division by zero");return a/Number(b)},Number(ordered[0]||0));break;case"formula":result=safeArithmetic(button.formula,values);break;case"join":result=ordered.join(" ");break;case"upper":result=String(ordered[0]||"").toUpperCase();break;case"lower":result=String(ordered[0]||"").toLowerCase();break;case"clear":incoming.forEach(id=>{const node=$(`[data-custom-id="${cssEscape(id)}"]`,root);if(node&&"value"in node)node.value=""});result="";break;default:result=ordered.join(" ")}}catch(error){result="Error: "+cleanText(error.message,120)}outgoing.forEach(id=>{const node=$(`[data-custom-id="${cssEscape(id)}"]`,root);if(node)node.textContent=String(result)})}
