    if((keyword=startsKeyword(original,map.elif))){indent=Math.max(0,indent-1);body=original.slice(keyword.length);line=`elif ${normalizeHumanExpression(body,map)}:`;opens=true}
    else if((keyword=startsKeyword(original,map.else))){indent=Math.max(0,indent-1);line="else:";opens=true}
    else if((keyword=startsKeyword(original,map.say))){body=original.slice(keyword.length).trim();line=`print(${body||JSON.stringify("")})`}
    else if((keyword=startsKeyword(original,map.set))){body=original.slice(keyword.length).trim();const match=body.match(/^([A-Za-z_]\w*)\s+(?:to|bilang|ay)\s+(.+)$/i);line=match?`${match[1]} = ${normalizeHumanExpression(match[2],map)}`:`# Check assignment: ${body}`}
    else if((keyword=startsKeyword(original,map.ask))){body=original.slice(keyword.length).trim();const match=body.match(/^([A-Za-z_]\w*)\s+(.+)$/);line=match?`${match[1]} = input(${match[2]})`:`input(${body})`}
    else if((keyword=startsKeyword(original,map.elif))){indent=Math.max(0,indent-1);body=original.slice(keyword.length);line=`elif ${normalizeHumanExpression(body,map)}:`;opens=true}
    else if((keyword=startsKeyword(original,map.if))){body=original.slice(keyword.length);line=`if ${normalizeHumanExpression(body,map)}:`;opens=true}
    else if((keyword=startsKeyword(original,map.repeat))){body=original.slice(keyword.length).trim();const count=body.match(/(.+?)\s+(?:times|beses)$/i)?.[1]||body;line=`for _ in range(${normalizeHumanExpression(count,map)}):`;opens=true}
    else if((keyword=startsKeyword(original,map.each))){body=original.slice(keyword.length).trim();const match=body.match(/^([A-Za-z_]\w*)\s+(?:in|sa)\s+(.+)$/i);line=match?`for ${match[1]} in ${normalizeHumanExpression(match[2],map)}:`:`# Check loop: ${body}`;opens=Boolean(match)}
    else if((keyword=startsKeyword(original,map.fn))){body=original.slice(keyword.length).trim();const match=body.match(/^([A-Za-z_]\w*)\s*(?:with|gamit)?\s*\(?([^)]*)\)?$/i);line=match?`def ${match[1]}(${match[2].replace(/\band\b|\bat\b/gi,",")}):`:`# Check function: ${body}`;opens=Boolean(match)}
    else if((keyword=startsKeyword(original,map.class))){body=original.slice(keyword.length).trim().replace(/\s+(?:extends|mana sa)\s+/i,"(");if(body.includes("(")&&!body.endsWith(")"))body+=")";line=`class ${body}:`;opens=true}
