function transpileSource(source,input,target,customPrint){const python=input.startsWith("human-")?humanToPython(source,input,customPrint):String(source);if(input==="yaml"){const project=parseProjectYAML(source);return({java:projectToSwing,cpp:projectToWin32,python:projectToPythonUI,swing:projectToSwing,tkinter:projectToTkinter,pyqt:projectToPyQt,kivy:projectToKivy}[target]||projectToPythonUI)(project)}if(target==="python"||["tkinter","pyqt","kivy","swing"].includes(target)){if(["tkinter","pyqt","kivy","swing"].includes(target))return `# GUI targets require GUI YAML input.\n# Select “GUI YAML”, then load a sample.\n\n${python}`;return python}return target==="cpp"?pythonToCpp(python):pythonToJava(python)}
const TRANSPILE_SAMPLES={python:`class Engineer:\n    def __init__(self, name):\n        self.name = name\n\n    def introduce(self):\n        return "Hello, " + self.name\n\nrey = Engineer("Rey")\nprint("Portfolio OS")\nfor i in range(3):\n    print(i)`,"human-en":`class Engineer\n    function introduce with name\n        say "Hello, " + name\n        return name\n    end\nend\nset person to "Rey"\nsay "Welcome, " + person\nrepeat 3 times\n    say "Building locally"\nend`,"human-fil":`klase Engineer\n    gawain ipakilala gamit pangalan\n        ipakita "Kumusta, " + pangalan\n        ibalik pangalan\n    wakas\nwakas\nitakda tao bilang "Rey"\nipakita "Maligayang pagdating, " + tao\nulitin 3 beses\n    ipakita "Lokal na bumubuo"\nwakas`,yaml:`app: "Connected Calculator"\ncomponents:\n  - id: input1\n    type: input\n    text: "First number"\n    x: 60\n    y: 80\n    width: 180\n  - id: input2\n    type: input\n    text: "Second number"\n    x: 60\n    y: 140\n    width: 180\n  - id: calculate\n    type: button\n    text: "Add"\n    x: 300\n    y: 110\n    width: 120\n    operation: add\n  - id: result\n    type: output\n    text: "Result"\n    x: 500\n    y: 110\n    width: 160\nconnections:\n  - from: input1\n    to: calculate\n  - from: input2\n    to: calculate\n  - from: calculate\n    to: result`};
function initTranspiler(win){const input=$("[data-transpile-input]",win),target=$("[data-transpile-target]",win),source=$("[data-transpile-source]",win),output=$("[data-transpile-output]",win),custom=$("[data-custom-print]",win);const run=()=>{try{output.textContent=transpileSource(source.value,input.value,target.value,custom.value)}catch(error){output.textContent="Compiler error: "+cleanText(error.message,220)}};$("[data-transpile-run]",win).addEventListener("click",run);$("[data-transpile-sample]",win).addEventListener("click",()=>{source.value=TRANSPILE_SAMPLES[input.value]||TRANSPILE_SAMPLES.python;run()});input.addEventListener("change",()=>{source.value=TRANSPILE_SAMPLES[input.value]||TRANSPILE_SAMPLES.python;if(input.value==="yaml"&&!['swing','tkinter','pyqt','kivy'].includes(target.value))target.value="swing";run()});target.addEventListener("change",run);$("[data-transpile-copy]",win).addEventListener("click",async()=>{try{await navigator.clipboard.writeText(output.textContent);toast("Copied","Generated source is on the clipboard.")}catch{toast("Copy unavailable","Select the output and copy it manually.")}});$("[data-transpile-download]",win).addEventListener("click",()=>{const ext={java:".java",cpp:".cpp",python:".py",swing:"-swing.java",tkinter:"-tkinter.py",pyqt:"-pyqt.py",kivy:"-kivy.py"}[target.value]||".txt";downloadText("portfolio-generated"+ext,output.textContent)});$("[data-install-transpiled]",win).addEventListener("click",()=>{const pkg={format:"portfolio-os-app/v1",name:"Transpiled Source",icon:"{ }",components:[{id:"title",type:"label",text:`${input.options[input.selectedIndex].text} → ${target.options[target.selectedIndex].text}`,x:35,y:28,w:600},{id:"source",type:"output",text:cleanText(output.textContent,1500),x:35,y:85,w:650}],connections:[],source:cleanText(output.textContent,12000),createdAt:new Date().toISOString()};installPackage(pkg);toast("Source installed","Open it from App Studio.")});run()}

