function localAnswer(question){const clean=cleanText(question,1200),tokens=[...new Set(clean.toLowerCase().match(/[a-z0-9+#]+/g)||[])].filter(x=>x.length>2);if(/java.*(example|sample|code)|(?:example|sample|code).*java/.test(clean.toLowerCase()))return `Here is a small Java example:\n\npublic record Skill(String name, int level) {}\n\nvar skills = List.of(new Skill("Java", 9), new Skill("AI", 8));\nskills.stream().filter(s -> s.level() >= 8).forEach(System.out::println);`;if(/python.*(example|sample|code)|(?:example|sample|code).*python/.test(clean.toLowerCase()))return `A compact Python example:\n\nskills = ["Java", "Python", "Angular", "AI"]\nstrong = [skill for skill in skills if len(skill) >= 4]\nprint(", ".join(strong))`;if(/contact|email|reach/.test(clean.toLowerCase()))return "You can reach Rey through the Email, LinkedIn, and GitHub links in About Rey. The resume is available in Resume.pdf.";const ranked=LOCAL_KNOWLEDGE.map(item=>({item,score:tokens.reduce((n,t)=>n+(item.tags.includes(t)?2:0)+(item.text.toLowerCase().includes(t)?1:0),0)})).sort((a,b)=>b.score-a.score);if(!ranked[0].score)return "I’m an offline portfolio assistant, so I’m strongest on Rey’s experience, projects, technical skills, Portfolio OS, and concise Java or Python examples. Try asking about one of those.";return ranked.slice(0,ranked[1]?.score?2:1).filter(x=>x.score>0).map(x=>x.item.text).join("\n\n")}
function initAgent(win){const chat=$("[data-agent-chat]",win),form=$("[data-agent-form]",win),input=$("textarea",form);const add=(role,text)=>{const article=make("article",role==="user"?"user-message":"assistant-message");article.append(make("span",null,role==="user"?"RV":"✦"),make("p",null,text));chat.append(article);chat.scrollTop=chat.scrollHeight};const ask=value=>{const query=cleanText(value,1200).trim();if(!query)return;add("user",query);input.value="";const thinking=make("article","assistant-message thinking");thinking.append(make("span",null,"✦"),make("p",null,"Thinking locally…"));chat.append(thinking);setTimeout(()=>{thinking.remove();add("assistant",localAnswer(query))},settings.motion?420:0)};form.addEventListener("submit",event=>{event.preventDefault();ask(input.value)});$$('.agent-suggestions button',win).forEach(button=>button.addEventListener("click",()=>ask(button.textContent)));$("[data-agent-clear]",win).addEventListener("click",()=>{chat.replaceChildren();add("assistant","New local conversation started. What would you like to explore?")})}

const installedKey=()=>"portfolio-os:installed:"+slug(settings.profile);
function getInstalledApps(){const apps=storage.get(installedKey(),[]);return Array.isArray(apps)?apps.slice(0,24):[]}
function installPackage(raw){const normalized=validateProject(raw);if(!normalized.components.length)throw new Error("Package needs at least one component.");const serialized=JSON.stringify(raw);if(serialized.length>SECURITY.maxPackage)throw new Error("Package exceeds the 1 MB local limit.");const apps=getInstalledApps(),record={...normalized,format:"portfolio-os-app/v1",icon:cleanText(raw.icon||"◆",3),source:cleanText(raw.source||"",12000),installedAt:new Date().toISOString(),packageId:slug(raw.name)+"-"+Date.now()};const same=apps.findIndex(app=>slug(app.name)===slug(record.name));if(same>=0)apps.splice(same,1,record);else apps.unshift(record);if(!storage.set(installedKey(),apps.slice(0,24)))throw new Error("Local storage is full.");const store=openWindows.get("store");if(store&&typeof store._renderInstalled==="function")store._renderInstalled();return record}
function initStore(win){const root=$("[data-installed-apps]",win),input=$("#appFileInput");const render=()=>{root.replaceChildren();const apps=getInstalledApps();if(!apps.length){const empty=make("div","empty-card");empty.append(make("b",null,"No installed apps"),make("span",null,"Build one in GUI Designer or import a package."));root.append(empty);return}apps.forEach(app=>{const card=make("article"),icon=make("span","app-icon store-icon",app.icon||"◆"),copy=make("div"),open=make("button",null,"Open"),remove=make("button",null,"×");copy.append(make("b",null,app.name),make("small",null,`${app.components.length} components · local`));open.type="button";open.addEventListener("click",()=>openCustomAppWindow(app,"custom-"+app.packageId));remove.type="button";remove.title="Uninstall";remove.addEventListener("click",()=>{storage.set(installedKey(),getInstalledApps().filter(item=>item.packageId!==app.packageId));render();toast("App uninstalled",app.name)});card.append(icon,copy,open,remove);root.append(card)})};win._renderInstalled=render;$("[data-import-app]",win).addEventListener("click",()=>input.click());input.onchange=async()=>{const file=input.files?.[0];input.value="";if(!file)return;if(file.size>SECURITY.maxPackage){toast("Import blocked","Packages are limited to 1 MB.");return}if(file.name.toLowerCase().endsWith(".exe")){toast("EXE registered safely","Browsers cannot execute native Windows binaries. Use the source installer generated by Transpiler.exe.");return}try{const text=await file.text();const raw=/\.ya?ml$/i.test(file.name)?parseProjectYAML(text):JSON.parse(text);installPackage(raw);render();toast("App installed",cleanText(raw.name||file.name,80))}catch(error){toast("Import failed",cleanText(error.message,180))}};render()}

async function requestInstall(){if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;toast("Install ready","Portfolio OS can now launch from your home screen.");return}toast("Install Portfolio OS","Use your browser menu and choose Add to Home Screen or Install app.")}
function initSettings(win){const name=$("[data-profile-name]",win),accent=$("[data-accent]",win),transparency=$("[data-transparency]",win),motion=$("[data-motion-toggle]",win);name.value=settings.profile;accent.value=settings.accent;transparency.value=settings.transparency;motion.checked=settings.motion;$$('[data-theme-choice]',win).forEach(button=>button.addEventListener("click",()=>{settings.theme=button.dataset.themeChoice;saveSettings();applySettings()}));accent.addEventListener("input",()=>{settings.accent=accent.value;saveSettings();applySettings()});transparency.addEventListener("input",()=>{settings.transparency=Number(transparency.value);saveSettings();applySettings()});motion.addEventListener("change",()=>{settings.motion=motion.checked;saveSettings();applySettings()});const changeProfile=()=>{const next=cleanText(name.value,40).trim();if(!next||next===settings.profile)return;saveSettings();const profiles=storage.get("portfolio-os:profiles",{active:settings.profile,entries:{}});profiles.active=next;storage.set("portfolio-os:profiles",profiles);loadSettings();name.value=settings.profile;toast("Profile switched",settings.profile)};name.addEventListener("change",changeProfile);name.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();changeProfile()}});$("[data-install-pwa]",win).addEventListener("click",requestInstall);$("[data-reset-settings]",win).addEventListener("click",()=>{settings=defaultSettings();saveSettings();applySettings();name.value=settings.profile;accent.value=settings.accent;transparency.value=settings.transparency;motion.checked=settings.motion;toast("Settings reset","The default Windows 11 theme is active.")})}
function initCalculator(win){const expression=$("[data-calc-expression]",win),output=$("[data-calc-output]",win);let value="";const show=()=>{expression.textContent=value;output.textContent=value||"0"};$$('[data-calc]',win).forEach(button=>button.addEventListener("click",()=>{const token=button.dataset.calc;if(token==="clear")value="";else if(token==="sign"){if(value&&/^-?\d+(?:\.\d+)?$/.test(value))value=String(-Number(value))}else if(token==="percent"){if(value&&/^-?\d+(?:\.\d+)?$/.test(value))value=String(Number(value)/100)}else if(token==="="){try{const result=safeArithmetic(value);expression.textContent=value+" =";value=String(result);output.textContent=value;return}catch{expression.textContent="Invalid expression";value="";output.textContent="0";return}}else if(value.length<80)value+=token;show()}));show()}

function finishBoot(){const boot=$("#bootScreen");if(boot.classList.contains("done"))return;boot.classList.add("done");setTimeout(()=>boot.setAttribute("aria-hidden","true"),700)}
function initDesktop(){
  loadSettings();updateClock();setInterval(updateClock,30000);const bootTimer=setTimeout(finishBoot,settings.motion?1750:120);$("#bootSkip").addEventListener("click",()=>{clearTimeout(bootTimer);finishBoot()});
  document.addEventListener("click",event=>{const launcher=event.target.closest("[data-open]");if(launcher){openApp(launcher.dataset.open);return}if(!event.target.closest(".panel-pop")&&!event.target.closest("#startButton")&&!event.target.closest("#trayButton")&&!event.target.closest("#taskSearch"))closePanels()});
  $("#startButton").addEventListener("click",event=>{event.stopPropagation();togglePanel("startMenu")});$("#taskSearch").addEventListener("click",event=>{event.stopPropagation();togglePanel("startMenu")});$("#trayButton").addEventListener("click",event=>{event.stopPropagation();togglePanel("quickPanel")});$("#startSearch").addEventListener("input",event=>{const query=event.target.value.trim().toLowerCase();$$('#startApps button').forEach(button=>button.hidden=!button.dataset.name.includes(query))});
  $("#desktop").addEventListener("contextmenu",event=>{if(event.target.closest(".app-window,.taskbar,.panel-pop"))return;event.preventDefault();closePanels();const menu=$("#contextMenu");menu.style.left=clamp(event.clientX,8,innerWidth-190)+"px";menu.style.top=clamp(event.clientY,8,innerHeight-150)+"px";menu.classList.add("open")});$("#refreshDesktop").addEventListener("click",()=>{const icons=$(".desktop-icons");icons.classList.remove("refreshed");requestAnimationFrame(()=>icons.classList.add("refreshed"));toast("Desktop refreshed","Everything is up to date.")});
  $("#lockButton").addEventListener("click",()=>{closePanels();const lock=$("#lockScreen");lock.classList.add("open");lock.setAttribute("aria-hidden","false")});$("#unlockButton").addEventListener("click",()=>{const lock=$("#lockScreen");lock.classList.remove("open");lock.setAttribute("aria-hidden","true")});
  $("#brightnessRange").addEventListener("input",event=>document.documentElement.style.setProperty("--brightness",String(Number(event.target.value)/100)));$("#focusToggle").addEventListener("click",event=>{event.currentTarget.classList.toggle("active");document.body.classList.toggle("focus-mode");toast("Focus mode",document.body.classList.contains("focus-mode")?"Ambient motion and desktop distractions reduced.":"Desktop restored.")});
  $("#installPwaTop").addEventListener("click",requestInstall);window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();deferredInstall=event;$("#installPwaTop").hidden=false});window.addEventListener("appinstalled",()=>toast("Portfolio OS installed","Launch it like a native app."));
  if("serviceWorker"in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));
  const wallpaper=$(".wallpaper");$("#desktop").addEventListener("pointermove",event=>{if(!settings.motion||innerWidth<=820||event.target.closest(".app-window,.panel-pop,.taskbar"))return;const x=(event.clientX/innerWidth-.5)*-7,y=(event.clientY/innerHeight-.5)*-7;wallpaper.style.transform=`scale(1.03) translate(${x}px,${y}px)`});
  document.addEventListener("keydown",event=>{if(event.key==="Escape"){closePanels();const focused=$(".app-window.focused");if(focused&&event.shiftKey)closeWindow(focused)}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==="k"){event.preventDefault();togglePanel("startMenu")}});
}
initDesktop();
